import{_ as r,o as a,c as e,al as d}from"./chunks/framework.BawR2jEz.js";const g=JSON.parse('{"title":"Лог","description":"Журнал действий exDoc — отслеживание операций, изменений и пользователей в модуле.","frontmatter":{"title":"Лог","description":"Журнал действий exDoc — отслеживание операций, изменений и пользователей в модуле."},"headers":[],"relativePath":"log/index.md","filePath":"log/index.md"}'),o={name:"log/index.md"};function n(i,t,l,s,h,c){return a(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="лог" tabindex="-1">Лог <a class="header-anchor" href="#лог" aria-label="Permalink to &quot;Лог&quot;">​</a></h1><p>Лог — журнал действий, фиксирующий все операции в exDoc. Позволяет отслеживать кто, когда и что изменил.</p><h2 id="открытие-лога" tabindex="-1">Открытие лога <a class="header-anchor" href="#открытие-лога" aria-label="Permalink to &quot;Открытие лога&quot;">​</a></h2><p>Нажмите иконку <strong>Лог</strong> в верхнем меню. Если есть непросмотренные записи, на иконке отображается красная точка-индикатор.</p><h2 id="записи-лога" tabindex="-1">Записи лога <a class="header-anchor" href="#записи-лога" aria-label="Permalink to &quot;Записи лога&quot;">​</a></h2><p>Каждая запись содержит:</p><table tabindex="0"><thead><tr><th>Поле</th><th>Описание</th></tr></thead><tbody><tr><td>ID</td><td>Уникальный номер записи</td></tr><tr><td>Дата</td><td>Дата и время действия</td></tr><tr><td>Источник</td><td>Откуда пришла запись — раздел или операция модуля</td></tr><tr><td>Пользователь</td><td>Имя пользователя OpenCart</td></tr><tr><td>Информация</td><td>Описание действия (например, «Добавлен блок (Header ID: 42)»)</td></tr><tr><td>Детали</td><td>JSON с дополнительными данными (раскрывается по кнопке)</td></tr></tbody></table><h2 id="типы-записеи" tabindex="-1">Типы записей <a class="header-anchor" href="#типы-записеи" aria-label="Permalink to &quot;Типы записей&quot;">​</a></h2><p>Записи различаются по уровню и подсвечиваются цветом:</p><table tabindex="0"><thead><tr><th>Тип</th><th>Описание</th></tr></thead><tbody><tr><td><strong>Info</strong></td><td>Информационные сообщения — штатные операции (создание, редактирование, удаление)</td></tr><tr><td><strong>Error</strong></td><td>Ошибки</td></tr><tr><td><strong>Warn</strong></td><td>Предупреждения</td></tr><tr><td><strong>Debug</strong></td><td>Отладочная информация</td></tr><tr><td><strong>Critical</strong></td><td>Критические сбои</td></tr></tbody></table><p>Каждый тип можно включить или выключить через фильтры-переключатели над таблицей. Рядом — поле фильтра по источнику: оно отбирает записи по части названия.</p><h2 id="деиствия-над-логом" tabindex="-1">Действия над логом <a class="header-anchor" href="#деиствия-над-логом" aria-label="Permalink to &quot;Действия над логом&quot;">​</a></h2><p><strong>Экспорт JSON</strong> выгружает записи — ровно те, что отобраны текущими фильтрами, а не весь журнал целиком.</p><p><strong>Очистить</strong> удаляет записи журнала целиком и спрашивает подтверждение.</p><p>Насколько подробно вести журнал, задаётся в <a href="./../settings/">настройках логирования</a>: при выключенном подробном режиме записываются только значимые операции.</p><h2 id="фаиловыи-лог" tabindex="-1">Файловый лог <a class="header-anchor" href="#фаиловыи-лог" aria-label="Permalink to &quot;Файловый лог&quot;">​</a></h2><p>Помимо журнала в базе exDoc пишет критические ошибки в файл <code>exdoc_error.log</code> — он лежит в папке логов OpenCart и открывается отдельным окном из <strong>Настройки → Логирование</strong>. Файл обновляется по кругу: раз в 180 дней он начинается заново.</p><p>Файловый лог полезен там, где журнал в базе бессилен: если сбой произошёл до подключения к базе или во время самой записи в неё, в таблице следа не останется, а в файле он будет.</p><h2 id="детали-записи" tabindex="-1">Детали записи <a class="header-anchor" href="#детали-записи" aria-label="Permalink to &quot;Детали записи&quot;">​</a></h2><p>Кнопка <strong>Детали</strong> раскрывает JSON-объект с подробной информацией о действии. Данные отображаются в редакторе CodeMirror для удобного просмотра.</p><p>Помимо данных операции, каждая запись хранит IP-адрес пользователя и URL запроса.</p><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="./../getting-started/interface.html">Обзор интерфейса</a> — структура админ-панели</li><li><a href="./../settings/roles.html">Настройки → Роли</a> — управление правами доступа</li></ul>',23)])])}const b=r(o,[["render",n]]);export{g as __pageData,b as default};
